class Solution:
    def frequencySort(self, s: str) -> str:
        parts = []
        for ch in set(s):
            # Re-counting for every unique character is brute force.
            parts.append((s.count(ch), ch))
        parts.sort(reverse=True)
        return "".join(ch * count for count, ch in parts)

