from collections import Counter
import heapq

class Solution:
    def frequencySort(self, s: str) -> str:
        heap = [(-count, ch) for ch, count in Counter(s).items()]
        heapq.heapify(heap)
        result = []

        while heap:
            neg_count, ch = heapq.heappop(heap)
            result.append(ch * (-neg_count))

        return "".join(result)

